package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    public long timestamp;
    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String userId;
    public int schedulingClass;
    public int priority;
    public Double cpuRequest;
    public Double ramRequest;
    public Double diskRequest;
    public boolean differentMachineConstraint;

    public TaskEvent() {}

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        TaskEvent event = new TaskEvent();
        event.timestamp = Long.parseLong(tokens[0]);
        // tokens[1] is missing info
        event.jobId = Long.parseLong(tokens[2]);
        event.taskIndex = Integer.parseInt(tokens[3]);
        if (!tokens[4].isEmpty()) event.machineId = Long.parseLong(tokens[4]);
        event.eventType = Integer.parseInt(tokens[5]);
        event.userId = tokens[6];
        if (!tokens[7].isEmpty()) event.schedulingClass = Integer.parseInt(tokens[7]);
        if (!tokens[8].isEmpty()) event.priority = Integer.parseInt(tokens[8]);
        if (!tokens[9].isEmpty()) event.cpuRequest = Double.parseDouble(tokens[9]);
        if (!tokens[10].isEmpty()) event.ramRequest = Double.parseDouble(tokens[10]);
        if (!tokens[11].isEmpty()) event.diskRequest = Double.parseDouble(tokens[11]);
        if (tokens.length > 12 && !tokens[12].isEmpty()) {
            event.differentMachineConstraint = tokens[12].equals("1");
        }
        return event;
    }
}

package clusterdata.datatypes;

import java.io.Serializable;

public class JobEvent implements Serializable {
    public long timestamp;
    public long jobId;
    public int eventType;
    public String userId;
    public Integer schedulingClass;
    public String jobName;
    public String logicalJobName;

    public JobEvent() {}

    public static JobEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        JobEvent event = new JobEvent();
        event.timestamp = Long.parseLong(tokens[0]);
        // tokens[1] is missing info
        event.jobId = Long.parseLong(tokens[2]);
        event.eventType = Integer.parseInt(tokens[3]);
        event.userId = tokens[4];
        if (tokens.length > 5 && !tokens[5].isEmpty()) event.schedulingClass = Integer.parseInt(tokens[5]);
        if (tokens.length > 6) event.jobName = tokens[6];
        if (tokens.length > 7) event.logicalJobName = tokens[7];
        return event;
    }
}

