package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        // Task events stream: filter SUBMIT events and assign timestamps
        DataStream<TaskEvent> taskStream = env.addSource(AppBase.taskSourceOrTest(new TaskEventSource(taskInput)))
                .filter(event -> event.eventType == 0) // SUBMIT
                .assignTimestampsAndWatermarks(WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                        .withTimestampAssigner((SerializableTimestampAssigner<TaskEvent>) (event, timestamp) -> event.timestamp / 1000));

        // Job events stream: filter terminal events and assign timestamps
        DataStream<JobEvent> jobStream = env.addSource(AppBase.jobSourceOrTest(new JobEventSource(jobInput)))
                .filter(event -> event.eventType >= 3 && event.eventType <= 6) // FAIL, FINISH, KILL, LOST
                .assignTimestampsAndWatermarks(WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                        .withTimestampAssigner((SerializableTimestampAssigner<JobEvent>) (event, timestamp) -> event.timestamp / 1000));

        // Identify stages and count tasks per stage using session windows
        DataStream<Tuple2<Long, Long>> stageCounts = taskStream
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountTasks());

        // Find the longest stage for each job and emit once the job has finished
        DataStream<Tuple2<Long, Long>> longestSessions = stageCounts
                .connect(jobStream)
                .keyBy(t -> t.f0, j -> j.jobId)
                .process(new LongestSessionProcess(sesssize));

        if (outputPath != null) {
            longestSessions.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        public TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (path == null) return;
            try (InputStream is = new FileInputStream(path);
                 InputStream gzis = new GZIPInputStream(is);
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzis))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (!line.trim().isEmpty()) {
                        try {
                            ctx.collect(TaskEvent.fromString(line));
                        } catch (Exception e) {
                            // Skip malformed lines
                        }
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        public JobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (path == null) return;
            try (InputStream is = new FileInputStream(path);
                 InputStream gzis = new GZIPInputStream(is);
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzis))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (!line.trim().isEmpty()) {
                        try {
                            ctx.collect(JobEvent.fromString(line));
                        } catch (Exception e) {
                            // Skip malformed lines
                        }
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class CountTasks implements AggregateFunction<TaskEvent, Long, Long> {
        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            return accumulator + 1;
        }

        @Override
        public Long getResult(Long accumulator) {
            return accumulator;
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    public static class LongestSessionProcess extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, JobEvent, Tuple2<Long, Long>> {
        private final int sessSize;
        private ValueState<Long> maxCount;
        private ValueState<Boolean> jobFinished;

        public LongestSessionProcess(int sessSize) {
            this.sessSize = sessSize;
        }

        @Override
        public void open(Configuration parameters) {
            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Long.class, 0L));
            jobFinished = getRuntimeContext().getState(new ValueStateDescriptor<>("jobFinished", Boolean.class, false));
        }

        @Override
        public void processElement1(Tuple2<Long, Long> value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (value.f1 > maxCount.value()) {
                maxCount.update(value.f1);
            }
        }

        @Override
        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (jobFinished.value() == null || !jobFinished.value()) {
                jobFinished.update(true);
                // Register a timer to emit the result. Wait until all potential sessions have finished.
                ctx.timerService().registerEventTimeTimer(value.timestamp / 1000 + sessSize * 1000 + 1);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            if (jobFinished.value() != null && jobFinished.value()) {
                out.collect(new Tuple2<>(ctx.getCurrentKey(), maxCount.value()));
                maxCount.clear();
                jobFinished.clear();
            }
        }
    }
}

