        // Identify stages and count tasks per stage using session windows
        DataStream<Tuple2<Long, Long>> stageCounts = taskStream
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssize)))
                .aggregate(new CountTasks());

        // Find the longest stage for each job and emit once the job has finished
        DataStream<Tuple2<Long, Long>> longestSessions = stageCounts
                .connect(jobStream)
                .keyBy(t -> t.f0, j -> j.jobId)
                .process(new LongestSessionProcess(sesssize));

        if (outputPath != null) {
            longestSessions.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);
        }

        env.execute("LongestSessionPerJob");
    }

